import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"安装不上 / 打不开网页","description":"DSN、端口、Redis 启动 Ping、static_dir 空字符串、自编译未 yarn build。官方 Releases 不必拷 dist。","frontmatter":{"title":"安装不上 / 打不开网页","description":"DSN、端口、Redis 启动 Ping、static_dir 空字符串、自编译未 yarn build。官方 Releases 不必拷 dist。"},"headers":[],"relativePath":"faq/install.md","filePath":"faq/install.md","lastUpdated":1790057721000}`),a={name:`faq/install.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="安装不上-打不开网页" tabindex="-1">安装不上 / 打不开网页 <a class="header-anchor" href="#安装不上-打不开网页" aria-label="Permalink to “安装不上 / 打不开网页”">​</a></h1><table tabindex="0"><thead><tr><th>现象</th><th>检查</th></tr></thead><tbody><tr><td>不知道该下哪个包</td><td>Release 里按前缀 <code>KiriVers-&lt;系统&gt;-&lt;架构&gt;-</code> 选，见 <a href="/guide/install/#releases-files">如何选 Releases 文件</a>。解压出来的可执行文件叫 <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code></td></tr><tr><td>上次的下载链接今天 404</td><td>正常：包名末尾六位是二进制内容哈希，每次发版都变。收藏 Release 页面，不要收藏单个文件链接</td></tr><tr><td>Linux 报 <code>GLIBC_x.y not found</code></td><td><code>x86</code> / <code>armv7</code> / <code>riscv64</code> 三个包是 glibc ≥ 2.39 的交叉构建；老系统改用 <a href="/guide/install/docker">Docker</a>（musl，仅 amd64/arm64）或自编译</td></tr><tr><td>校验和怎么验</td><td><code>sha256sum -c SHA256SUMS.txt</code>（第一段是 11 个上传件）。第二段以 <code>#</code> 注释记录包内二进制，需解压后自行比对</td></tr><tr><td>进程立刻退出</td><td><code>postgres.dsn</code>；五路日志是否双 sink 全关；<code>changelog.default_entries &gt; max_entries</code></td></tr><tr><td><code>cache.driver=redis</code> 起不来</td><td>启动 Ping 失败。先起 Redis 或改回 <code>memory</code></td></tr><tr><td>连错端口</td><td>客户端 <code>:8080</code>，管理 <code>:8081</code></td></tr><tr><td>JSON 而不是登录页</td><td><code>admin.enabled</code>；<code>static_dir: &quot;&quot;</code> 关闭了 UI；自编译二进制未先构建管理台（没有 <code>index.html</code>）</td></tr><tr><td>官方 Releases 打不开 UI</td><td>官方二进制已嵌入管理台，不必再拷 <code>frontend/dist</code>。检查 <code>static_dir</code> 是否被设成空</td></tr></tbody></table><p>Windows 使用 <a href="/guide/install/manual">手动安装</a>，一键脚本只支持带 apt/yum 的 Linux。<code>static_dir</code> 指向管理台；文档站 VitePress <code>dist</code> 不是管理台。</p>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};